import pandas as pd
q=pd.read_csv('quality_inspections.csv');b=pd.read_csv('production_batches.csv');o=pd.read_csv('operator_shift_log.csv')
x=q.merge(b,on=['batch_id','product_id']).merge(o,left_on=['production_day','machine_id'],right_on=['day','machine_id'])
med=x.groupby('product_id').rejected_pct.median();x['ex']=x.rejected_pct-x.product_id.map(med);x['rej']=x.inspection_result.eq('REJECTED')
for col in ['operator_id','production_day']:
 z=x.groupby(col).agg(n=('batch_id','size'),rej=('rej','sum'),hi20=('ex',lambda s:(s>.02).sum()),hi40=('ex',lambda s:(s>.04).sum()),maxex=('ex','max'),meanex=('ex','mean')).sort_values(['hi40','hi20'],ascending=False)
 print('\n',col);print(z.head(30).to_string())
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":20000});
text(r.output);

